   732                                  "AddNodes: Node type not found in nodestore");
   733              retval = UA_STATUSCODE_BADTYPEDEFINITIONINVALID;
   734              goto cleanup;
   735          }
   736
   737          UA_Boolean  typeOk = UA_FALSE;
   738          switch(node->nodeClass) {
   739              case UA_NODECLASS_DATATYPE:
   740                  typeOk = type->nodeClass == UA_NODECLASS_DATATYPE;
   741                  break;
   742              case UA_NODECLASS_METHOD:
   743                  typeOk = type->nodeClass == UA_NODECLASS_METHOD;
   744                  break;
   745              case UA_NODECLASS_OBJECT:
   746                  typeOk = type->nodeClass == UA_NODECLASS_OBJECTTYPE;
   747                  break;
   748              case UA_NODECLASS_OBJECTTYPE:
   749                  typeOk = type->nodeClass == UA_NODECLASS_OBJECTTYPE;
   750                  break;
   751              case UA_NODECLASS_REFERENCETYPE:
   752                  typeOk = type->nodeClass == UA_NODECLASS_REFERENCETYPE;
   753                  break;
   754              case UA_NODECLASS_VARIABLE:
   755                  typeOk = type->nodeClass == UA_NODECLASS_VARIABLETYPE;
   756                  break;
   757              case UA_NODECLASS_VARIABLETYPE:
   758                  typeOk = type->nodeClass == UA_NODECLASS_VARIABLETYPE;
   759                  break;
   760              case UA_NODECLASS_VIEW:
   761                  typeOk = type->nodeClass == UA_NODECLASS_VIEW;
   762                  break;
   763              default:
