   775          if(!server->bootstrapNS0 && node->nodeClass == UA_NODECLASS_VARIABLE) {
   776              if(((const UA_VariableTypeNode*)type)->isAbstract) {
   777                  /* Abstract variable is allowed if parent is a children of a base data variable */
   778                  const UA_NodeId variableTypes = UA_NODEID_NUMERIC(0, UA_NS0ID_BASEDATAVARIABLETYPE);
   779                  /* A variable may be of an object type which again is below BaseObjectType */
   780                  const UA_NodeId objectTypes = UA_NODEID_NUMERIC(0, UA_NS0ID_BASEOBJECTTYPE);
