   797                  /* Object node created of an abstract ObjectType. Only allowed if within BaseObjectType folder */
   798                  const UA_NodeId objectTypes = UA_NODEID_NUMERIC(0, UA_NS0ID_BASEOBJECTTYPE);
   799                  UA_NodeId refs[2];
   800                  refs[0] = UA_NODEID_NUMERIC(0, UA_NS0ID_HASSUBTYPE);
   801                  refs[1] = UA_NODEID_NUMERIC(0, UA_NS0ID_HASCOMPONENT);
